fields.formula:
if((Remaining_Quantity__c + Pending_Capacity__c)  <=0,
        if(Waitlist_Enabled__c==false,
            if(Event__r.Waitlist_Enabled__c==true, 
                if( OR(Event__r.Event_End_Date_Time_GMT__c < NOW(),Sales_End_Date_Time_GMT__c  < NOW()),
                    if(Hidden__c ==false,'Registration ended (Public)','Registration ended (Private)'),
                    if( AND(Event__r.Remaining_Capacity__c<=0 ,OR(Event__r.Remaining_Waitlist_Capacity__c >0 , ISNULL(Event__r.Remaining_Waitlist_Capacity__c))),
                      'Sold Out, Waitlist Open','Sold Out, Waitlist Closed'
                    )
                ),
                if( OR(Event__r.Event_End_Date_Time_GMT__c < NOW(),Sales_End_Date_Time_GMT__c  < NOW()),
                    if(Hidden__c ==false,'Registration ended (Public)','Registration ended (Private)'),
                    'Sold Out'
                )
            ),
            if( OR(Event__r.Event_End_Date_Time_GMT__c < NOW(),Sales_End_Date_Time_GMT__c  < NOW()),
                 if(Hidden__c ==false,'Registration ended (Public)','Registration ended (Private)'),
                 if(OR(Remaining_Waitlist_Capacity__c >0 , ISNULL(Remaining_Waitlist_Capacity__c)),'Sold Out, Waitlist Open','Sold Out, Waitlist Closed')
            )
        ),
        if(Hidden__c ==false , 
            if(Event__r.Event_End_Date_Time_GMT__c < NOW(),'Registration ended (Public)',
                if(Sales_End_Date_Time_GMT__c  < NOW(),'Registration ended (Public)',
                    if(ISNULL(Sales_Start_Date_Time_GMT__c) ,'Registration active (Public)',
                        if(AND(Sales_Start_Date_Time_GMT__c <=NOW(),Sales_End_Date_Time_GMT__c> NOW()),'Registration active (Public)',
                        'Pending Registration Start Date (Public)'
                        )
                    )

                )
            ),
            if(Event__r.Event_End_Date_Time_GMT__c < NOW(),'Registration ended (Private)',
                if(Sales_End_Date_Time_GMT__c  < NOW(),'Registration ended (Private)',
                    if(ISNULL(Sales_Start_Date_Time_GMT__c), 'Registration active (Private)',
                        if(AND(Sales_Start_Date_Time_GMT__c <=NOW(),Sales_End_Date_Time_GMT__c> NOW()),'Registration active (Private)',
                        'Pending Registration Start Date (Private)'
                        )
                    )
                )
            )
        )   
)

if(TEXT(Status__c) =='Canceled','Canceled',if(TEXT(Status__c)=='Completed','Event Ended',if(OR(NOT(Visible__c) , TEXT(Hide_Register_Button__c)=='Yes'),'Disabled Event',if( Event_End_Date_Time_GMT__c  < NOW(),'Event Ended' ,
    if(Remaining_Capacity__c<=0 ,
        if(Waitlist_Enabled__c == false ,
            if(Waitlist_Enabled_On_EventItem__c==true,
                if(ISNULL(Waitlist_Capacity__c),'Sold Out, Waitlist Open',if(Remaining_Waitlist_Capacity__c<=0, 'Sold Out, Waitlist Closed','Sold Out, Waitlist Open')),
                if(OR(Remaining_Waitlist_Capacity__c<=0,ISNULL(Remaining_Waitlist_Capacity__c)), 'Sold Out','Sold Out, Waitlist Open')
            ),
            if(OR(Remaining_Waitlist_Capacity__c >0 , ISNULL(Remaining_Waitlist_Capacity__c)),'Sold Out, Waitlist Open','Sold Out, Waitlist Closed')
        ),
        'Event Active'
    )
))))

if(AND(NOT(ISNULL(Maximum_Registrants__c)), (Remaining_Seats__c + Pending_Capacity__c) <=0) ,
    if(Waitlist_Enabled__c == false ,'Sold Out',
        if( OR(Event__r.Event_End_Date_Time_GMT__c < NOW(),End_Date_Time_GMT__c  < NOW()),
            if(Hide_On_Event_Page__c ==false,'Registration ended (Public)','Registration ended (Private)'),
            if(OR(Remaining_Waitlist_Capacity__c >0 , ISNULL(Remaining_Waitlist_Capacity__c)),'Sold Out, Waitlist Open','Sold Out, Waitlist Closed')
        )


    ),

    if(Hide_On_Event_Page__c ==false , 
            if(Event__r.Event_End_Date_Time_GMT__c < NOW(),'Registration ended (Public)',
                if(End_Date_Time_GMT__c  < NOW(),'Registration ended (Public)',
                    if(ISNULL(Start_Date_Time_GMT__c) ,'Registration active (Public)',
                        if(AND(Start_Date_Time_GMT__c <=NOW(),End_Date_Time_GMT__c> NOW()),'Registration active (Public)',
                        'Pending Registration Start Date (Public)'
                        )
                    )

                )
            ),
            if(Event__r.Event_End_Date_Time_GMT__c < NOW(),'Registration ended (Private)',
                if(End_Date_Time_GMT__c  < NOW(),'Registration ended (Private)',
                    if(ISNULL(Start_Date_Time_GMT__c), 'Registration active (Private)',
                        if(AND(Start_Date_Time_GMT__c <=NOW(),End_Date_Time_GMT__c> NOW()),'Registration active (Private)',
                        'Pending Registration Start Date (Private)'
                        )
                    )
                )
            )
    )

)
